INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Passt Klasse A gut für große Unternehmensnetzwerke?', 2, '[{"text": "Ja", "correct": true, "because": "Bietet viele Hostadressen"}, {"text": "Nein", "correct": false, "because": "Typischer Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse eignet sich für Multicast-Übertragungen?', 3, '[{"text": "Klasse D", "correct": true, "because": "Reserviert für Multicast"}, {"text": "Klasse A", "correct": false, "because": "Für Unicast"}, {"text": "Klasse C", "correct": false, "because": "Für kleine Netze"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse B ist für mittelgroße Firmen geeignet. b) Klasse E ist für kommerzielle Netze gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse E ist experimentell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was übersehe ich bei der Wahl der Klasse für ein Unternehmen?', 4, '[{"text": "Hostanzahl", "correct": false, "because": "Entscheidend für Größe"}, {"text": "Netzwerkanforderungen", "correct": false, "because": "Bestimmen Klasse"}, {"text": "Designpräferenzen", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Klasse D für IPTV genutzt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Multicast-Anwendung"}, {"text": "Nein", "correct": false, "because": "Typischer Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse wähle ich für ein kleines Büro mit 50 Geräten?', 3, '[{"text": "Klasse C", "correct": true, "because": "Bis zu 254 Hosts"}, {"text": "Klasse A", "correct": false, "because": "Zu groß"}, {"text": "Klasse D", "correct": false, "because": "Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einsatzgebiete passen zu den Adressklassen?', 5, '[{"text": "Klasse A für globale Firmen", "correct": true, "because": "Viele Hosts"}, {"text": "Klasse D für Streaming", "correct": true, "because": "Multicast"}, {"text": "Klasse B für Einzelgeräte", "correct": false, "because": "Mittelgroß"}, {"text": "Klasse E für Unternehmen", "correct": false, "because": "Experimentell"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Klasse C ist ideal für kleine Netze. b) Klasse A ist für Multicast. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse A ist Unicast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für den Einsatz in einem Unternehmen unwichtig?', 4, '[{"text": "Netzwerkgröße", "correct": false, "because": "Bestimmt Klasse"}, {"text": "Hostanforderungen", "correct": false, "because": "Definiert Bedarf"}, {"text": "Softwareversion", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird Klasse B oft in Firmen mit 500 Geräten genutzt?', 2, '[{"text": "Ja", "correct": true, "because": "Bis zu 65.534 Hosts"}, {"text": "Nein", "correct": false, "because": "Passender Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse wähle ich für ein Unternehmen mit 10.000 Geräten?', 4, '[{"text": "Klasse A", "correct": true, "because": "Über 16 Mio. Hosts"}, {"text": "Klasse C", "correct": false, "because": "Nur 254 Hosts"}, {"text": "Klasse D", "correct": false, "because": "Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Klasse E für Multicast geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Klasse D ist für Multicast"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist entscheidend für den Einsatz in einem Unternehmen?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Passt Klasse an Bedarf"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär"}, {"text": "Zufälligkeit", "correct": false, "because": "Planung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse D ist für Gruppenkommunikation. b) Klasse B ist für kleine Büros.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) eher mittelgroß"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einsatzgebiete passen zu den Klassen?', 5, '[{"text": "Klasse C für SOHO", "correct": true, "because": "Kleine Netze"}, {"text": "Klasse D für Videokonferenzen", "correct": true, "because": "Multicast"}, {"text": "Klasse A für kleine Teams", "correct": false, "because": "Zu groß"}, {"text": "Klasse E für Streaming", "correct": false, "because": "Experimentell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was spielt beim Einsatzgebiet keine Rolle?', 3, '[{"text": "Hostanzahl", "correct": false, "because": "Definiert Klasse"}, {"text": "Netzwerktyp", "correct": false, "because": "Bestimmt Anwendung"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Eignet sich Klasse C für ein Netz mit 200 Geräten?', 3, '[{"text": "Ja", "correct": true, "because": "Bis 254 Hosts"}, {"text": "Nein", "correct": false, "because": "Passender Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Klasse D für Unternehmensnetze genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Multicast"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse passt für eine Firma mit 1.000 Mitarbeitern?', 4, '[{"text": "Klasse B", "correct": true, "because": "Bis 65.534 Hosts"}, {"text": "Klasse C", "correct": false, "because": "Zu klein"}, {"text": "Klasse D", "correct": false, "because": "Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse ist typisch für Multicast in einem Unternehmen?', 3, '[{"text": "224.0.0.1", "correct": true, "because": "Klasse D, alle Geräte"}, {"text": "192.168.1.1", "correct": false, "because": "Klasse C"}, {"text": "10.0.0.1", "correct": false, "because": "Klasse A"}]');
